const page_status = this.getValue('page_status');

if (page_status === 'View' || !value) {
    callback();
    return;
}

let organizationId = this.getVarGlobal('deptParentId');
if(organizationId === '0'){
    organizationId = this.getVarSystem('deptIds').split(',')[0];
}

db.collection("mc2_stock_movement")
    .where({ item_assembly_batch: value, organization_id: organizationId })
    .get()
    .then(response => {
        const matchingItemAssembly = response.data || [];

        if (matchingItemAssembly.length === 0) {
            callback();
            return;
        }

        if (page_status === 'Edit') {
            const currentItemAssemblyId = this.getValue('id');
            const isSamePO = matchingItemAssembly.some(item_assembly => item_assembly.id === currentItemAssemblyId);
            callback(isSamePO ? undefined : 'Item assembly number already exists.');
        } else {
            callback('Item assembly number already exists.');
        }
    })
    .catch(error => {
        console.error("Error checking item assembly:", error);
        callback("Error validating item assembly number.");
    });

