      [`stock_movement_1.${rowIndex}.total_quantity`]: 0,
      [`stock_movement_1.${rowIndex}.quantity_uom`]: "",
      [`stock_movement_1.${rowIndex}.stock_summary`]: "",
      [`stock_movement_1.${rowIndex}.balance_id`]: "",
      [`stock_movement_1.${rowIndex}.temp_qty_data`]: "",
      [`stock_movement_1.${rowIndex}.temp_hu_data`]: "",
      [`stock_movement_1.${rowIndex}.item_name_1`]: "",
      [`stock_movement_1.${rowIndex}.item_desc_1`]: "",
